using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using DungeonGame.Quests;
using DungeonGame.Dialogue;
public static class BuildGatheringQuest
{
 const string Root="Assets/Quests/SuppliesForTheRoad";
 public const string ScenePath="Assets/Scenes/Test_Scenes/GatheringQuest_Test.unity";
 static void Folder(string p){if(AssetDatabase.IsValidFolder(p))return;int i=p.LastIndexOf('/');Folder(p.Substring(0,i));AssetDatabase.CreateFolder(p.Substring(0,i),p.Substring(i+1));}
 static T Asset<T>(string name) where T:ScriptableObject{string p=Root+"/"+name+".asset";var a=AssetDatabase.LoadAssetAtPath<T>(p);if(a==null){a=ScriptableObject.CreateInstance<T>();AssetDatabase.CreateAsset(a,p);}return a;}
 static QuestDialogueAction Action(string name,QuestDefinition q,QuestDialogueCommand c,string stage=""){var a=Asset<QuestDialogueAction>(name);a.quest=q;a.command=c;a.stageId=stage;EditorUtility.SetDirty(a);return a;}
 static QuestDialogueCondition Condition(string name,QuestDefinition q,QuestDialogueCheck c,string stage=""){var a=Asset<QuestDialogueCondition>(name);a.quest=q;a.check=c;a.stageId=stage;EditorUtility.SetDirty(a);return a;}
 static DialogueResponse Response(string text,DialogueAction a=null,params DialogueCondition[] conditions)=>new DialogueResponse{text=text,action=a,conditions=conditions};
 static void Catalog(GameObject root,QuestDefinition q,bool undo){var c=root.GetComponentInChildren<QuestController>(true);if(c==null)throw new Exception("Existing quest controller missing");if(undo)Undo.RecordObject(c,"Register gathering quest");c.quests=(c.quests??Array.Empty<QuestDefinition>()).Where(x=>x!=null&&x!=q).Concat(new[]{q}).ToArray();EditorUtility.SetDirty(c);if(PrefabUtility.IsPartOfPrefabInstance(c))PrefabUtility.RecordPrefabInstancePropertyModifications(c);}
 public static object Build()
 {
 if(EditorApplication.isPlaying)throw new Exception("Preserve Play Mode");var scene=SceneManager.GetActiveScene();if(!scene.path.EndsWith("Gameplay_Test.unity"))throw new Exception("Expected open Gameplay_Test");
 var player=scene.GetRootGameObjects().First(x=>x.GetComponentInChildren<PlayerGathering>(true)!=null);
 var sourceNodes=scene.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<ResourceNode>(true)).ToArray();if(sourceNodes.Length<3)throw new Exception("Existing three resource nodes are required");
 var logs=AssetDatabase.LoadAssetAtPath<Item>("Assets/ResourceNodes/Logs.asset");var ore=AssetDatabase.LoadAssetAtPath<Item>("Assets/ResourceNodes/CopperOre.asset");var potion=AssetDatabase.LoadAssetAtPath<Item>("Assets/GamePlay/ScriptableObjects/Items/Consumables/Health Potion.asset");if(logs==null||ore==null||potion==null)throw new Exception("Resource item definitions missing");
 Folder(Root);var q=Asset<QuestDefinition>("SuppliesForTheRoad");q.id="supplies-for-the-road";q.title="Supplies for the Road";q.summary="Quartermaster Nessa needs firewood, copper for repairs, and a healing draught before the next expedition.";q.experienceReward=75;q.itemRewards=new[]{new InventoryItemAmount{item=potion,count=2}};
 q.stages=new[]{new QuestStage{id="camp-supplies",journal="Bring Nessa two logs and one copper ore. Chop trees and mine the copper rocks in the test yard; supplies already in your bag also count.",objectives=new[]{new QuestObjective{id="logs",description="Bring two logs",type=QuestObjectiveType.PossessItem,item=logs,count=2,consumeOnTurnIn=true},new QuestObjective{id="copper",description="Bring one copper ore",type=QuestObjectiveType.PossessItem,item=ore,consumeOnTurnIn=true}}},new QuestStage{id="healing-draught",journal="The repairs are covered. Fill a healing potion at the spring and bring it to Nessa. Leave one extra bag slot free for her reward.",objectives=new[]{new QuestObjective{id="potion",description="Bring one healing potion",type=QuestObjectiveType.PossessItem,item=potion,count=1,consumeOnTurnIn=true}}}};if(!q.Validate(out string reason))throw new Exception(reason);EditorUtility.SetDirty(q);
 var start=Action("AcceptSupplies",q,QuestDialogueCommand.Start);var supplies=Action("DeliverSupplies",q,QuestDialogueCommand.TurnInStage,"camp-supplies");var finish=Action("DeliverDraught",q,QuestDialogueCommand.TurnInStage,"healing-draught");var done=Condition("Completed",q,QuestDialogueCheck.Completed);var supplyStage=Condition("SupplyStage",q,QuestDialogueCheck.ActiveStage,"camp-supplies");var potionStage=Condition("PotionStage",q,QuestDialogueCheck.ActiveStage,"healing-draught");var suppliesReady=Condition("SuppliesReady",q,QuestDialogueCheck.ReadyToTurnIn,"camp-supplies");var potionReady=Condition("DraughtReady",q,QuestDialogueCheck.ReadyToTurnIn,"healing-draught");var canStart=Condition("CanAccept",q,QuestDialogueCheck.CanStart);var end=AssetDatabase.LoadAssetAtPath<ServiceDialogueAction>("Assets/Dialogue/EndDialogue.asset");
 var conversation=Asset<DialogueConversation>("NessaConversation");conversation.entryNode="offer";conversation.conditionalEntries=new[]{new DialogueEntry{nodeId="complete",conditions=new DialogueCondition[]{done}},new DialogueEntry{nodeId="draught",conditions=new DialogueCondition[]{potionStage}},new DialogueEntry{nodeId="supplies",conditions=new DialogueCondition[]{supplyStage}}};
 conversation.nodes=new[]{new DialogueNode{id="offer",text="An expedition runs on preparation. Two logs for the fire, one piece of copper for repairs. After that, we'll see to the medicine. Can you lend a hand?",responses=new[]{Response("I'll bring the supplies.",start,canStart),Response("Maybe later.",end)}},new DialogueNode{id="supplies",text="Two logs and one copper ore. The trees and copper rocks are close by. I need the supplies in your bag before I can put them to work.",responses=new[]{Response("Here are the logs and copper.",supplies,suppliesReady),Response("I'll return with the supplies.",end)}},new DialogueNode{id="draught",text="That will keep the fire burning and the tools in one piece. One last thing: a healing potion from the spring. Bring it back and I'll restock your medicine pouch.",responses=new[]{Response("Here is the healing potion.",finish,potionReady),Response("I'll fetch the potion.",end)}},new DialogueNode{id="complete",text="Firewood stacked, tools repaired, medicine packed. That's an expedition ready to leave. Take these potions, and thank you for seeing the job through.",responses=new[]{Response("Safe travels, Nessa.",end)}}};EditorUtility.SetDirty(conversation);
 var holder=PrefabUtility.LoadPrefabContents("Assets/Prefabs/Player/PlayerHolder.prefab");try{Catalog(holder,q,false);PrefabUtility.SaveAsPrefabAsset(holder,"Assets/Prefabs/Player/PlayerHolder.prefab");}finally{PrefabUtility.UnloadPrefabContents(holder);}Catalog(player,q,true);
 const string npcPath="Assets/Prefabs/WorldInteract/Quartermaster_Nessa.prefab";var npcAsset=AssetDatabase.LoadAssetAtPath<GameObject>(npcPath);var npcRoot=npcAsset!=null?PrefabUtility.LoadPrefabContents(npcPath):(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/WorldInteract/NPC_Main.prefab"));
 try{npcRoot.name="Quartermaster_Nessa";var npc=npcRoot.GetComponentInChildren<DialogueNpc>(true);npc.speakerName="Quartermaster Nessa";npc.conversation=conversation;foreach(var agent in npcRoot.GetComponentsInChildren<UnityEngine.AI.NavMeshAgent>(true))agent.enabled=false;PrefabUtility.SaveAsPrefabAsset(npcRoot,npcPath);}finally{if(npcAsset!=null)PrefabUtility.UnloadPrefabContents(npcRoot);else UnityEngine.Object.DestroyImmediate(npcRoot);}
 var liveNpc=scene.GetRootGameObjects().FirstOrDefault(x=>x.name=="Quartermaster_Nessa");if(liveNpc==null){liveNpc=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(npcPath),scene);Undo.RegisterCreatedObjectUndo(liveNpc,"Place gathering quest giver");liveNpc.transform.position=new Vector3(-4,0,2);liveNpc.transform.rotation=Quaternion.Euler(0,180,0);PrefabUtility.RecordPrefabInstancePropertyModifications(liveNpc.transform);}
 var tree=scene.GetRootGameObjects().FirstOrDefault(x=>x.name=="ResourceNode_Tree_West");if(tree==null){tree=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/WorldInteract/ResourceNode_Tree.prefab"),scene);tree.name="ResourceNode_Tree_West";Undo.RegisterCreatedObjectUndo(tree,"Place second gathering tree");tree.transform.position=new Vector3(-.8f,0,3.8f);PrefabUtility.RecordPrefabInstancePropertyModifications(tree.transform);}
 EditorSceneManager.MarkSceneDirty(scene);AssetDatabase.SaveAssets();if(!EditorSceneManager.SaveScene(scene,ScenePath,true))throw new Exception("Unable to save isolated gathering quest fixture");return new{implemented=true,quest=AssetDatabase.GetAssetPath(q),npc=npcPath,scene=ScenePath,originalDirty=scene.isDirty};
 }
}
